const toArray = (field) => {
  if (!field || field.values == null) {
    return [];
  }
  const v = field.values.buffer || field.values;
  const n = typeof v.length === 'number' ? v.length : 0;
  const out = [];
  for (let i = 0; i < n; i += 1) {
    out.push(typeof v.get === 'function' ? v.get(i) : v[i]);
  }
  return out;
};

const seriesList = (context.panel.data && context.panel.data.series) || [];
const series = seriesList[0];
if (!series) {
  return {
    backgroundColor: 'transparent',
    title: {
      text: 'No data',
      left: 'center',
      top: 'middle',
      textStyle: { color: '#888', fontSize: 14 },
    },
  };
}

const day = toArray(series.fields.find((f) => f.name === 'Day'));
const production = toArray(series.fields.find((f) => f.name === 'Production'));
const consumption = toArray(series.fields.find((f) => f.name === 'Consumption'));

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
  },
  legend: {
    data: ['Production', 'Consumption'],
    bottom: 0,
    textStyle: { color: '#ccccdc' },
  },
  grid: {
    left: 48,
    right: 24,
    top: 28,
    bottom: 48,
  },
  xAxis: {
    type: 'category',
    data: day,
    axisLabel: { color: '#9b9b9b' },
  },
  yAxis: {
    type: 'value',
    name: 'kWh',
    nameTextStyle: { color: '#9b9b9b' },
    axisLabel: { color: '#9b9b9b' },
    splitLine: { lineStyle: { color: 'rgba(120,120,120,0.25)' } },
  },
  series: [
    {
      name: 'Production',
      type: 'bar',
      data: production,
      barMaxWidth: 28,
      itemStyle: { color: '#FF9830' },
    },
    {
      name: 'Consumption',
      type: 'line',
      data: consumption,
      symbol: 'circle',
      symbolSize: 6,
      lineStyle: { width: 3, color: '#B877D9' },
      itemStyle: { color: '#B877D9' },
      z: 3,
    },
  ],
};
